insert into lancamentos_financeiros
  (tipo, atividade, centro_custo_id, descricao, valor, data, mes, vencimento, fornecedor, cultura_id, conag_id, cnpj_nota, criado_por, observacao)
select 'receita',
       s.atividade,
       c.id,
       btrim(s.entidade),
       s.valor,
       s.data::date,
       s.mes,
       s.vencimento::date,
       btrim(s.entidade),
       cu.id,
       s.conag_id,
       nullif(btrim(s.cnpj_nota), ''),
       'Conag',
       'Conag receita - ' || s.plano_conta
  from receita_nova s
  join centros_custo c on plano_norm(c.nome) = plano_norm(s.plano_conta)
  left join lateral (
        select id from culturas
         where s.cultura is not null
           and plano_norm(nome) = plano_norm(s.cultura)
         limit 1) cu on true
on conflict (conag_id) where conag_id is not null do nothing;

with receita_nova (conag_id, atividade, cultura, entidade, plano_conta, data, mes, valor, cnpj_nota, vencimento) as (
